command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="049626c146b158520f82d692d6a44a97c381fc85"
$targets=@{
  "work/metadata-sort-correctness-20261006"="631df62a63445a8249cfe7c8d99a1a4dc5a41ed3";
  "work/metadata-sort-baseline-harness-20261006"="aac3ecef564dc380f0a4d8c75668c135390fa267";
}
Set-Location -LiteralPath $repo
& git fetch origin main --no-tags --prune
if($LASTEXITCODE -ne 0){throw "branch cleanup fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){
  throw "main moved before branch cleanup"
}
foreach($entry in $targets.GetEnumerator()){
  $branch=$entry.Key
  $expected=$entry.Value
  $remoteLine=(& git ls-remote --heads origin ("refs/heads/"+$branch)).Trim()
  if(!$remoteLine){
    Write-Host "BRANCH_ALREADY_ABSENT=$branch"
    continue
  }
  $observed=($remoteLine -split "\s+")[0]
  if($observed -ne $expected){
    throw "branch cleanup lease mismatch: $branch expected=$expected observed=$observed"
  }
  & git push origin --delete $branch
  if($LASTEXITCODE -ne 0){throw "branch deletion failed: $branch"}
  $after=(& git ls-remote --heads origin ("refs/heads/"+$branch)).Trim()
  if($after){throw "branch still exists after deletion: $branch"}
  Write-Host "BRANCH_DELETED=$branch"
}
Write-Host "BRANCH_CLEANUP=PASS"
